// ---------------- Operations: dashboard, today, team tasks, weekly report, production overview ----------------
export function OpsDashboard() {
  const db = useDb()
  const issues = MAGAZINES.map(m => ({ m, issue: recordsOf(db, 'issues', m.key).filter(i => i.status !== 'Published').sort((a, b) => String(a.deadline).localeCompare(String(b.deadline)))[0] }))
  const esc = recordsOf(db, 'escalations').filter(e => e.status !== 'Resolved')
  const pending = ['social-posts', 'video-jobs', 'magazine-jobs'].flatMap(c => recordsOf(db, c).filter(r => r.approval === 'Pending'))
  const late = db.deliverables.filter(d => d.status !== 'Delivered' && d.due < todayIso()).length
  return <div className="stack" style={{ gap: 16 }}>
    <div className="grid c4"><Stat label="Magazines at risk" value={issues.filter(x => x.issue && String(x.issue.deadline) < addDays(todayIso(), 7)).length} sub="deadline within 7 days" /><Stat label="Needs Raoof's attention" value={esc.length} tone={esc.length ? 'warn' : undefined} /><Stat label="Needs SK approval" value={pending.length} /><Stat label="Deliverables late" value={late} tone={late ? 'warn' : undefined} /></div>
    <div className="card wrap"><div className="hd"><h2>Magazines at a glance</h2><a className="btn sm" href="#/ops/magazines">Open Magazines</a></div><table className="tbl"><thead><tr><th>Magazine</th><th>Issue</th><th>Deadline</th><th>Stage</th><th>Status</th></tr></thead><tbody>{issues.map(({ m, issue }) => { const d = issue ? Math.round((new Date(String(issue.deadline)).getTime() - Date.now()) / 864e5) : undefined; const st = !issue ? 'No issue planned' : d! < 0 ? 'Critical' : d! < 7 ? 'At Risk' : 'On Track'; return <tr key={m.key}><td><a className="lnk" href={`#/${m.key}`}>{m.brand}</a></td><td>{issue ? String(issue.issue) : '—'}</td><td className="muted">{issue ? fmtDate(String(issue.deadline)) : '—'}</td><td className="small">{issue ? String(issue.status) : '—'}</td><td><span className={`pill plain ${st === 'On Track' ? 'good' : st === 'At Risk' ? 'warn' : st === 'Critical' ? 'maple' : 'none'}`}>{st}</span></td></tr> })}</tbody></table></div>
    <div className="grid c2"><div className="card"><div className="hd"><h2>Needs Raoof's attention</h2></div><table className="tbl"><tbody>{esc.map(e => <tr key={e.id}><td><b>{String(e.problem)}</b><div className="muted small">{String(e.label)} · raised by {personName(String(e.raisedBy))} · {fmtDate(String(e.raisedOn))}</div></td></tr>)}{esc.length === 0 && <tr><td className="empty small">Nothing raised.</td></tr>}</tbody></table></div><div className="card"><div className="hd"><h2>Needs SK approval</h2><a className="btn sm" href="#/approvals">Approvals</a></div><table className="tbl"><tbody>{pending.map(p => <tr key={p.id}><td><b>{String(p.post ?? p.title ?? p.piece)}</b></td></tr>)}{pending.length === 0 && <tr><td className="empty small">Nothing pending.</td></tr>}</tbody></table></div></div>
  </div>
}
const OPS_DAILY = ['Check Today and clear overdue items', 'Confirm every finished meeting has notes', 'Chase missing client files', 'Review deliverables due this week', 'Check podcast edits in progress', 'Post scheduled social content', 'Reply to vendor emails', 'Update magazine issue status', 'Check invoices sent and paid', 'Log escalations', 'Confirm tomorrow\'s recordings', 'Back up the CRM (Admin → Data)', 'Review approvals waiting', 'Send end-of-day report']
const OPS_WEEKDAY: Record<number, string[]> = { 1: ['Weekly report to Raoof', 'Plan the week\'s social posts', 'Review all magazine deadlines', 'Check onboarding progress', 'Review training sessions'], 2: ['Vendor payments review', 'Podcast publishing check'], 3: ['Mid-week deliverables review', 'Website feedback triage'], 4: ['Issue readiness check', 'Approvals sweep'], 5: ['Friday weekly scorecard', 'Archive finished tasks', 'Plan next week'] }
export function OpsToday() {
  const db = useDb()
  const day = new Date().getDay()
  const rec = recordsOf(db, 'daily-checklist').find(r => r.date === todayIso() && r.person === `ops:${db.settings.currentUserId}`)
  const done: string[] = (rec?.done as string[]) ?? []
  const toggle = (k: string) => { const next = done.includes(k) ? done.filter(x => x !== k) : [...done, k]; if (rec) updateRecord('daily-checklist', rec.id, { done: next }); else addRecord('daily-checklist', '', { date: todayIso(), person: `ops:${db.settings.currentUserId}`, done: next }) }
  const due = db.tasks.filter(t => t.status !== 'Done' && t.due === todayIso()), overdue = db.tasks.filter(t => t.status !== 'Done' && t.due && t.due < todayIso())
  const List = ({ title, items, prefix }: { title: string; items: string[]; prefix: string }) => <div className="card"><div className="hd"><h2>{title}<span className="sub">{items.filter(i => done.includes(prefix + i)).length} of {items.length} done</span></h2></div><div className="bd stack" style={{ gap: 6 }}>{items.map(i => <label key={i} className="small inline"><input type="checkbox" checked={done.includes(prefix + i)} onChange={() => toggle(prefix + i)} /> <span style={{ textDecoration: done.includes(prefix + i) ? 'line-through' : 'none' }}>{i}</span></label>)}</div></div>
  return <div className="grid c2"><List title={`Daily checklist for ${fmtDate(todayIso())}`} items={OPS_DAILY} prefix="d:" /><div className="stack" style={{ gap: 16 }}><List title={`${['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'][day]} checklist`} items={OPS_WEEKDAY[day] ?? ['No extra items today']} prefix="w:" /><div className="card"><div className="hd"><h2>Tasks due today<span className="sub">{due.length}</span> · overdue <span className="sub">{overdue.length}</span></h2><a className="btn sm" href="#/tasks">All tasks</a></div><table className="tbl"><tbody>{[...overdue, ...due].map(t => <tr key={t.id}><td><b>{t.title}</b><div className="muted small">{personName(t.assigneeId)}</div></td><td className="muted" style={t.due! < todayIso() ? { color: 'var(--warn)' } : undefined}>{fmtDate(t.due)}</td></tr>)}{due.length + overdue.length === 0 && <tr><td className="empty small">Nothing due today.</td></tr>}</tbody></table></div></div></div>
}
export function TeamTasks() {
  const db = useDb()
  const route = useRoute()
  const f = route[2] ?? 'today'
  const openT = db.tasks.filter(t => t.status !== 'Done')
  const filters: Array<[string, string, (t: typeof openT[0]) => boolean]> = [['today', 'Due Today', t => t.due === todayIso()], ['overdue', 'Overdue', t => !!t.due && t.due < todayIso()], ['week', 'This Week', t => !!t.due && t.due <= addDays(todayIso(), 7)], ['blocked', 'Blocked', t => t.status === 'In progress' && !!t.due && t.due < todayIso()], ['client', 'Waiting for Client', t => /client|files/i.test(t.title)], ['approval', 'Waiting for Approval', t => /approv/i.test(t.title)], ['all', 'All open', () => true]]
  const cur = filters.find(x => x[0] === f) ?? filters[0]
  const rows = openT.filter(cur[2])
  return <><nav className="tabs">{filters.map(([k, l, fn]) => <a key={k} href={`#/ops/team-tasks/${k}`} className={f === k ? 'on' : ''}>{l}<span className="n">{openT.filter(fn).length}</span></a>)}</nav>
    <div className="grid side"><div className="card wrap"><table className="tbl"><thead><tr><th>Title</th><th>Assignee</th><th>Priority</th><th>Deadline</th><th>Status</th></tr></thead><tbody>{rows.map(t => <tr key={t.id}><td><b>{t.title}</b></td><td>{personName(t.assigneeId)}</td><td><span className={`pill plain ${t.priority === 'High' ? 'maple' : t.priority === 'Medium' ? 'warn' : 'none'}`}>{t.priority}</span></td><td className="muted">{fmtDate(t.due)}</td><td>{t.status}</td></tr>)}{rows.length === 0 && <tr><td colSpan={5} className="empty small">Nothing here.</td></tr>}</tbody></table></div><div className="card"><div className="hd"><h2>Workload by person</h2></div><table className="tbl"><thead><tr><th>Person</th><th className="num">Open</th><th className="num">Overdue</th></tr></thead><tbody>{db.people.map(p => <tr key={p.id}><td>{p.name}</td><td className="num">{openT.filter(t => t.assigneeId === p.id).length}</td><td className="num" style={openT.filter(t => t.assigneeId === p.id && t.due && t.due < todayIso()).length ? { color: 'var(--warn)' } : undefined}>{openT.filter(t => t.assigneeId === p.id && t.due && t.due < todayIso()).length}</td></tr>)}</tbody></table></div></div></>
}
export function WeeklyReport() {
  const db = useDb()
  const wk = addDays(todayIso(), -((new Date().getDay() + 6) % 7))
  const existing = recordsOf(db, 'weekly-reports').find(r => r.week === wk && r.person === db.settings.currentUserId)
  const [f, setF] = useState({ done: String(existing?.done ?? ''), need: String(existing?.need ?? ''), next: String(existing?.next ?? '') })
  const [toast, say] = useToast()
  const auto = `Closed: ${fmtMoney(db.deals.filter(d => d.stage === 'Won' && d.updatedAt.slice(0, 10) >= wk).reduce((s, d) => s + d.value, 0))}. Published: ${db.content.filter(c => c.status === 'Published' && (c.publishDate ?? '') >= wk).length} pieces. Deliverables done: ${db.deliverables.filter(d => d.status === 'Delivered').length}. Open escalations: ${recordsOf(db, 'escalations').filter(e => e.status !== 'Resolved').length}.`
  const save = (send: boolean) => { const data = { week: wk, person: db.settings.currentUserId, ...f, auto, sent: send }; if (existing) updateRecord('weekly-reports', existing.id, data); else addRecord('weekly-reports', '', data); say(send ? 'Sent to Raoof' : 'Saved') }
  return <div className="card" style={{ maxWidth: 760 }}><div className="hd"><h2>Weekly report to Raoof<span className="sub">week of {fmtDate(wk)}</span></h2></div><div className="bd form"><p className="note">{auto}</p><Field label="What got done"><textarea value={f.done} onChange={(e: any) => setF({ ...f, done: e.target.value })} /></Field><Field label="What do you need from Raoof"><textarea value={f.need} onChange={(e: any) => setF({ ...f, need: e.target.value })} /></Field><Field label="Top priorities for next week"><textarea value={f.next} onChange={(e: any) => setF({ ...f, next: e.target.value })} /></Field><div className="inline"><button className="btn" onClick={() => save(false)}>Save</button><button className="btn" onClick={() => { navigator.clipboard?.writeText(`${auto}\n\nDone:\n${f.done}\n\nNeed from Raoof:\n${f.need}\n\nNext week:\n${f.next}`); say('Copied') }}>Copy</button><button className="btn pri" onClick={() => save(true)}>Send to Raoof</button></div></div><Toast msg={toast} /></div>
}
export function ProductionOverview() {
  const db = useDb()
  const jobs = [...recordsOf(db, 'social-posts').map(r => ({ who: String(r.maker ?? ''), what: String(r.post), due: String(r.due ?? ''), status: String(r.status), kind: 'Social' })), ...recordsOf(db, 'video-jobs').map(r => ({ who: String(r.editor ?? ''), what: String(r.title), due: String(r.due ?? ''), status: String(r.status), kind: 'Video' })), ...recordsOf(db, 'magazine-jobs').map(r => ({ who: String(r.designer ?? ''), what: String(r.piece), due: String(r.due ?? ''), status: String(r.status), kind: 'Magazine' })), ...db.deliverables.filter(d => d.status !== 'Delivered').map(d => ({ who: d.ownerId ?? '', what: d.what, due: d.due, status: d.status, kind: 'Deliverable' }))].filter(j => !/posted|published|approved/i.test(j.status))
  const overdue = jobs.filter(j => j.due && j.due < todayIso())
  const by = db.people.filter(p => ['Design', 'Editorial', 'Web', 'Operations'].includes(p.role) || jobs.some(j => j.who === p.id))
  return <div className="stack" style={{ gap: 16 }}><div className="grid c3"><Stat label="Open work" value={jobs.length} /><Stat label="Overdue" value={overdue.length} tone={overdue.length ? 'warn' : undefined} /><Stat label="People with work" value={by.filter(p => jobs.some(j => j.who === p.id)).length} /></div><div className="card wrap"><div className="hd"><h2>Open work by person</h2></div><table className="tbl"><thead><tr><th>Person</th><th className="num">Social</th><th className="num">Video</th><th className="num">Magazine</th><th className="num">Deliverables</th><th className="num">Overdue</th></tr></thead><tbody>{by.map(p => <tr key={p.id}><td><b>{p.name}</b><div className="muted small">{p.role}</div></td>{['Social', 'Video', 'Magazine', 'Deliverable'].map(k => <td key={k} className="num">{jobs.filter(j => j.who === p.id && j.kind === k).length}</td>)}<td className="num" style={overdue.filter(j => j.who === p.id).length ? { color: 'var(--warn)' } : undefined}>{overdue.filter(j => j.who === p.id).length}</td></tr>)}</tbody></table></div>{overdue.length > 0 && <div className="card"><div className="hd"><h2>Overdue work</h2></div><table className="tbl"><tbody>{overdue.map((j, i) => <tr key={i}><td><span className="tag">{j.kind}</span></td><td><b>{j.what}</b></td><td>{personName(j.who)}</td><td style={{ color: 'var(--warn)' }}>{fmtDate(j.due)}</td><td className="small">{j.status}</td></tr>)}</tbody></table></div>}</div>
}
export function MeetingNotes() { return <Team tab="meetings" title="Meeting Notes" blurb="One list of meetings. Add notes to a finished one: what was discussed, what to send, and next steps. A finished meeting with no notes is flagged on Today." /> }
export function SettingsPage() { return <Admin tab="settings" title="Settings" /> }
